  "test": "import pytest
from datetime import datetime
from browser_use.telemetry.service import ProductTelemetry

class DummyClient:
    def __init__(self):
        self.captures = []
    def capture(self, distinct_id, event, properties):
        self.captures.append({
            "distinct_id": distinct_id,
            "event": event,
            "properties": properties,
        })
    def flush(self):
        pass

def test_capture_includes_timestamp(monkeypatch):
    dummy = DummyClient()
    pt = ProductTelemetry()
    # Replace the internal PostHog client with our dummy
    pt._posthog_client = dummy

    class Event:
        name = "test_event"
        properties = {"foo": "bar"}

    pt.capture(Event())
    assert len(dummy.captures) == 1
    props = dummy.captures[0]["properties"]
    assert "timestamp" in props
    # Verify that the timestamp is a valid ISO format string
    datetime.fromisoformat(props["timestamp"]))
